(164045, 9232, 5472, '<td valign="top">a little purple but I bet it looked more blue in person!</td>', 'a little purple but I bet it looked more blue in person!', '2002-12-02 11:37:00.000000', NULL, 1),
(164046, 9232, 5212, '<td valign="top">Great shot.</td>', 'Great shot.', '2002-12-02 16:08:00.000000', NULL, 1),
