INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(164386, 9119, 2553, '<td valign="top">One of my favorites this week.  I love the colors, the composition, and I must have a *thing* about photos of doors, because I seem to be drawn to them.  At first, I didn''t care for the darker area at the top of, and above, the door, but the more I look at it, the more I think it suits the photo.  It gives it a more mysterious feel. lhall</td>', 'One of my favorites this week.  I love the colors, the composition, and I must have a *thing* about photos of doors, because I seem to be drawn to them.  At first, I didn''t care for the darker area at the top of, and above, the door, but the more I look at it, the more I think it suits the photo.  It gives it a more mysterious feel. lhall', '2002-12-04 19:26:29.000000', NULL, 1),
(164387, 9154, 3087, '<td valign="top">test<br/>kavey</td>', 'testkavey', '2002-12-04 19:27:41.000000', NULL, 1),
(164388, 9045, 2553, '<td valign="top">A beautiful shot with good composition, the person standing to her right distracts me a tiny bit, but since the angle of the pants is in parallel with her arm, the distraction is minimal.  lhall</td>', 'A beautiful shot with good composition, the person standing to her right distracts me a tiny bit, but since the angle of the pants is in parallel with her arm, the distraction is minimal.  lhall', '2002-12-04 19:29:26.000000', NULL, 1),
(164390, 9250, 2553, '<td valign="top">I cannot believe that more people didn''t do flags for this challenge - I certainly thought about it!!  I''m glad now that I didn''t because I couldn''t have beat this.  Very nice, I love the art feel of it.  lhall</td>', 'I cannot believe that more people didn''t do flags for this challenge - I certainly thought about it!!  I''m glad now that I didn''t because I couldn''t have beat this.  Very nice, I love the art feel of it.  lhall', '2002-12-04 19:30:47.000000', NULL, 1),
