INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(165190, 8995, 2170, '<td valign="top">Awesome!!  Well done -- would be great for the motion challenge too.  muckpond</td>', 'Awesome!!  Well done -- would be great for the motion challenge too.  muckpond', '2002-12-05 21:16:33.000000', NULL, 1),
(165192, 9160, 2170, '<td valign="top">Very nice shape and texture.  The white is pretty blasted out in some places, and there are some shadows that are a bit unfortunate.  An interesting photo, nonetheless.  muckpond</td>', 'Very nice shape and texture.  The white is pretty blasted out in some places, and there are some shadows that are a bit unfortunate.  An interesting photo, nonetheless.  muckpond', '2002-12-05 21:17:31.000000', NULL, 1),
(165193, 9154, 2170, '<td valign="top">Very nicely done.  The lemon adds a great "twist" to the checkerboard technique.  Would love to have a little "how to" on how you pulled this off after the challenge.  muckpond</td>', 'Very nicely done.  The lemon adds a great "twist" to the checkerboard technique.  Would love to have a little "how to" on how you pulled this off after the challenge.  muckpond', '2002-12-05 21:18:23.000000', NULL, 1),
(165194, 9119, 2170, '<td valign="top">A great idea and I love the off-centeredness (is that a word?)  The bluish cast on the white walls is unfortunate, as is the harsh lighting on the wall.  Still, overall a great picture that is perfect for the challenge.  muckpond</td>', 'A great idea and I love the off-centeredness (is that a word?)  The bluish cast on the white walls is unfortunate, as is the harsh lighting on the wall.  Still, overall a great picture that is perfect for the challenge.  muckpond', '2002-12-05 21:19:34.000000', NULL, 1),
(165195, 8987, 3306, '<td valign="top">Beautiful blue eyes but the face has a greenish blotchy tint. very sharp focus.</td>', 'Beautiful blue eyes but the face has a greenish blotchy tint. very sharp focus.', '2002-12-05 21:19:39.000000', NULL, 1),
